bool MeshModelClass::read_per_face_texcoord_ids(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	// The per-face texture coordinate ids (three 4-byte ids per polygon) are skipped: nothing reads them.
	int size = PolyCount * 3 * 4;
	if (cload.Cur_Chunk_Length() == size) {
		cload.Seek(size);
		return true;
	}
	return false;
}

