// FUNCTION: BFME2 0x00188760 size=392 name=?read_vertex_colors@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=B hypothesis:K
bool MeshModelClass::read_vertex_colors(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	// Only two unique colour arrays survive the move to hardware T&L: the first array found is loaded, and the pass's
	// DCG source is pointed at it either way (a second DCG chunk is not used).
	if (CurMatDesc->Has_Color_Array(0) == false) {
		W3dRGBStruct color;
		unsigned *dcg = Get_Color_Array(0, true);

		for (int i = 0; i < Get_Vertex_Count(); i++) {

			if (cload.Read(&color, sizeof(W3dRGBStruct)) != sizeof(W3dRGBStruct)) {
				return false;
			}

			Vector4 col;
			col.Set((float)color.R / 255.0f, (float)color.G / 255.0f, (float)color.B / 255.0f, 1.0f);
			dcg[i] = DXWrapper::Convert_Color(col);
		}
	}
	CurMatDesc->Set_DCG_Source(context->CurPass, VertexMaterialClass::COLOR1);

	return true;
}


// FUNCTION: BFME2 0x001888F0 size=190 name=?read_vertex_material_ids@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=B hypothesis:K
bool MeshModelClass::read_vertex_material_ids(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	unsigned long vmat;

	MeshMatDescClass *matdesc = DefMatDesc;
	if (matdesc->Has_Material_Data(context->CurPass)) {
		matdesc = &(context->AlternateMatDesc);
	}

	if (cload.Cur_Chunk_Length() == 1 * sizeof(unsigned long)) {
		cload.Read(&vmat, sizeof(vmat));
		matdesc->Set_Single_Material(context->Peek_Vertex_Material(vmat), context->CurPass);
	} else {
		for (int i = 0; i < Get_Vertex_Count(); i++) {
			cload.Read(&vmat, sizeof(unsigned long));
			matdesc->Set_Material(i, context->Peek_Vertex_Material(vmat), context->CurPass);
		}
	}
	return true;
}

// FUNCTION: BFME2 0x001889B0 size=307 name=?read_shader_ids@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=B hypothesis:K
bool MeshModelClass::read_shader_ids(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	MeshMatDescClass *matdesc = DefMatDesc;
	if (DefMatDesc->Has_Shader_Data(context->CurPass)) {
		matdesc = &(context->AlternateMatDesc);
	}

	unsigned long shaderid;
	if (cload.Cur_Chunk_Length() == 1 * sizeof(unsigned long)) {
		cload.Read(&shaderid, sizeof(shaderid));
		ShaderClass shader = context->Peek_Shader(shaderid);
		matdesc->Set_Single_Shader(shader, context->CurPass);

		// turn on sorting of pass 0 has non-zero dest blend (unless alpha testing on)
		if ((context->CurPass == 0) &&
			(shader.Get_Dst_Blend_Func() != ShaderClass::DSTBLEND_ZERO) &&
			(shader.Get_Alpha_Test() == ShaderClass::ALPHATEST_DISABLE) &&
			(SortLevel == SORT_LEVEL_NONE))
		{
			Set_Flag(SORT, true);
		}
	} else {
		for (int i = 0; i < Get_Polygon_Count(); i++) {
			cload.Read(&shaderid, sizeof(unsigned long));
			ShaderClass shader = context->Peek_Shader(shaderid);
			matdesc->Set_Shader(i, shader, context->CurPass);

			// turn on sorting of pass 0 has non-zero dest blend (unless alpha testing on)
			if ((context->CurPass == 0) &&
				(shader.Get_Dst_Blend_Func() != ShaderClass::DSTBLEND_ZERO) &&
				(shader.Get_Alpha_Test() == ShaderClass::ALPHATEST_DISABLE) &&
				(SortLevel == SORT_LEVEL_NONE))
			{
				Set_Flag(SORT, true);
			}
		}
	}
	return true;
}


// FUNCTION: BFME2 0x00188AF0 size=190 name=?read_Rva00188AF0@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=?:placeholder tier=B hypothesis:K
bool MeshModelClass::read_Rva00188AF0(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	// The FX shader ids: the same layout as read_shader_ids, with the objects kept in the context's pointer array.
	MeshMatDescClass *matdesc = DefMatDesc;
	if (DefMatDesc->Has_Pass_Buffer(context->CurPass)) {
		matdesc = &(context->AlternateMatDesc);
	}

	unsigned long shaderid;
	if (cload.Cur_Chunk_Length() == 1 * sizeof(unsigned long)) {
		cload.Read(&shaderid, sizeof(shaderid));
		matdesc->Set_Single_FXShader((RefCountClass *)context->Peek_Texture(shaderid), context->CurPass);
	} else {
		for (int i = 0; i < Get_Polygon_Count(); i++) {
			cload.Read(&shaderid, sizeof(unsigned long));
			matdesc->Set_FXShader(i, (RefCountClass *)context->Peek_Texture(shaderid), context->CurPass);
		}
	}

	return true;
}


// FUNCTION: BFME2 0x00188BB0 size=562 name=?read_dcg@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=B hypothesis:K
bool MeshModelClass::read_dcg(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	MeshMatDescClass *matdesc = DefMatDesc;
	if (DefMatDesc->Get_DCG_Source(context->CurPass) != VertexMaterialClass::MATERIAL) {
		matdesc = &context->AlternateMatDesc;
	}

	if (matdesc->Has_Color_Array(0) == false) {
		unsigned *dcg = matdesc->Get_Color_Array(0);
		// W3D words store red and blue in the opposite order from D3DCOLOR.
		cload.Read(dcg, Get_Vertex_Count() * 2 * 2);
		for (int i = 0; i < Get_Vertex_Count(); i++) {
			unsigned c = dcg[i];
			unsigned lo = (c >> 16) & 0xFF;
			unsigned hi = (c & 0xFF) << 16;
			dcg[i] = lo | hi | (c & 0xFF00FF00);
		}
	} else if (context->PrelitChunkID == W3D_CHUNK_PRELIT_VERTEX) {
		W3dRGBAStruct color;
		unsigned *dcg = matdesc->Get_Color_Array(0);
		for (int i = 0; i < Get_Vertex_Count(); i++) {
			cload.Read(&color, sizeof(color));
			Vector4 col = DXWrapper::Convert_Color(dcg[i]);
			col.W = (float)color.A / 255.0f;
			dcg[i] = DXWrapper::Convert_Color(col);
		}
	}

	matdesc->Set_DCG_Source(context->CurPass, VertexMaterialClass::COLOR1);
	return true;
}


// FUNCTION: BFME2 0x00188DF0 size=848 name=?read_dig@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=B hypothesis:K
bool MeshModelClass::read_dig(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	MeshMatDescClass *matdesc = DefMatDesc;
	if (context->Already_Loaded_DIG()) {
		matdesc = &context->AlternateMatDesc;
	}
	context->Notify_Loaded_DIG_Chunk(true);

	if (matdesc->Has_Color_Array(0) == false) {
		W3dRGBAStruct color;
		unsigned *dcg = matdesc->Get_Color_Array(0);
		for (int i = 0; i < Get_Vertex_Count(); i++) {
			cload.Read(&color, sizeof(color));
			Vector4 col;
			col.X = (float)color.R * (1.0f / 255.0f);
			col.Y = (float)color.G * (1.0f / 255.0f);
			col.Z = (float)color.B * (1.0f / 255.0f);
			col.W = 1.0f;
			dcg[i] = DXWrapper::Convert_Color(col);
		}
	} else {
		W3dRGBAStruct color;
		unsigned *dcg = matdesc->Get_Color_Array(0);
		for (int i = 0; i < Get_Vertex_Count(); i++) {
			cload.Read(&color, sizeof(color));
			Vector4 col = DXWrapper::Convert_Color(dcg[i]);
			col.X *= (float)color.R * (1.0f / 255.0f);
			col.Y *= (float)color.G * (1.0f / 255.0f);
			col.Z *= (float)color.B * (1.0f / 255.0f);
			dcg[i] = DXWrapper::Convert_Color(col);
		}
	}

	matdesc->Set_DCG_Source(context->CurPass, VertexMaterialClass::COLOR1);
	return true;
}


// FUNCTION: BFME2 0x00189140 size=293 name=?read_texture_ids@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=B hypothesis:K
bool MeshModelClass::read_texture_ids(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	unsigned int texture_id;
	int pass = context->CurPass;
	int stage = context->CurTexStage;
	MeshMatDescClass *matdesc = DefMatDesc;
	if (DefMatDesc->Has_Texture_Data(pass, stage)) {
		matdesc = &context->AlternateMatDesc;
	}

	if (cload.Cur_Chunk_Length() == sizeof(texture_id)) {
		cload.Read(&texture_id, sizeof(texture_id));
		matdesc->Set_Single_Texture(context->Peek_Texture_Handle(texture_id), pass, stage);
	} else {
		for (int polygon = 0; polygon < Get_Polygon_Count(); ++polygon) {
			cload.Read(&texture_id, sizeof(texture_id));
			if (texture_id != 0xffffffff) {
				matdesc->Set_Texture(polygon, context->Peek_Texture_Handle(texture_id), pass, stage);
			}
		}
	}
	return true;
}



// FUNCTION: BFME2 0x00189270 size=125 name=?get_sort_flags@MeshModelClass@@IBEIH@Z evidence=N:ledger tier=B hypothesis:K
unsigned int MeshModelClass::get_sort_flags(int pass_index) const
{
	// One bit per static sort category the pass_index's shaders fall into.
	unsigned int categories = 0;
	if (CurMatDesc->ShaderArray[pass_index] != 0) {
		for (int poly = 0; poly < CurMatDesc->ShaderArray[pass_index]->Get_Count(); poly++)
			categories |= 1 << CurMatDesc->ShaderArray[pass_index]->Get_Array()[poly].Get_SS_Category();
		return categories;
	}
	ShaderClass single = CurMatDesc->Shader[pass_index];
	return 1 << single.Get_SS_Category();
}

// FUNCTION: BFME2 0x001892F0 size=48 name=?get_sort_flags@MeshModelClass@@IBEIXZ evidence=N:ledger tier=B hypothesis:K
unsigned int MeshModelClass::get_sort_flags(void) const
{
	unsigned int combined = 0;
	for (int index = 0; index < Get_Pass_Count(); index++)
		combined |= get_sort_flags(index);
	return combined;
}

// FUNCTION: BFME2 0x00189320 size=61 name=?compute_static_sort_levels@MeshModelClass@@IAEXXZ evidence=N:ledger tier=B hypothesis:K
void MeshModelClass::compute_static_sort_levels(void)
{
	// The first pass alone can force the opaque level; otherwise the
	// combination of every pass's flags picks a level (0, 10, 15 or 20).
	if (get_sort_flags(0) == 1) {
		Set_Sort_Level(0);
		return;
	}
	switch (get_sort_flags()) {
	case 3:
		Set_Sort_Level(0);
		break;
	case 4:
		Set_Sort_Level(10);
		break;
	case 8:
		Set_Sort_Level(15);
		break;
	default:
		Set_Sort_Level(20);
		break;
	}
}

