// FUNCTION: BFME2 0x001896D0 size=179 name=?read_texcoords@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A
bool MeshModelClass::read_texcoords(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	W3dTexCoordStruct texcoord;
	int elementcount = cload.Cur_Chunk_Length() / sizeof(W3dTexCoordStruct);

	context->TempUVArray.Uninitialised_Grow(elementcount);
	Vector2 *uvarray = &context->TempUVArray[0];

	if (uvarray != NULL) {
		for (int i = 0; i < VertexCount; i++) {
			if (cload.Read(&texcoord, sizeof(W3dTexCoordStruct)) != sizeof(W3dTexCoordStruct)) {
				return false;
			}
			uvarray[i].Set(texcoord.U, 1.0f - texcoord.V);
		}
		DefMatDesc->Install_UV_Array(context->CurPass, context->CurTexStage, uvarray, elementcount);
	}
	return true;
}

// FUNCTION: BFME2 0x00189790 size=655 name=?read_per_tri_materials@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A
bool MeshModelClass::read_per_tri_materials(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	if (context->Header.NumMaterials == 1) return true;

	TriIndex *polys = Poly->Get_Array();

	bool multi_mtl = (context->Vertex_Material_Count() > 1);
	bool multi_tex = (context->Texture_Count() > 1);
	bool multi_shad = (context->Shader_Count() > 1);

	if (!multi_mtl) {
		Set_Single_Material(context->Peek_Legacy_Vertex_Material(0));
	}
	if (!multi_tex) {
		Set_Single_Texture(context->Peek_Legacy_Texture(0));
	}
	if (!multi_shad) {
		Set_Single_Shader(context->Peek_Legacy_Shader(0));
	}

	/*
	** Read in each polygon's material id and assign pointer to the
	** shader, texture, and vertex material as needed.
	*/
	for (int i = 0; i < Get_Polygon_Count(); i++) {

		// read in the mat id for this poly
		unsigned short matid;

		if (cload.Read(&matid, sizeof(unsigned short)) != sizeof(unsigned short)) {
			return false;
		}

		if (multi_shad) {
			Set_Shader(i, context->Peek_Legacy_Shader(matid));
		}
		if (multi_tex) {
			Set_Texture(i, context->Peek_Legacy_Texture(matid));
		}
		if (multi_mtl) {
			Set_Material(polys[i].I, context->Peek_Legacy_Vertex_Material(matid));
			Set_Material(polys[i].J, context->Peek_Legacy_Vertex_Material(matid));
			Set_Material(polys[i].K, context->Peek_Legacy_Vertex_Material(matid));
		}
	}

	return true;
}
// FUNCTION: BFME2 0x00189A20 size=293 name=?read_stage_texcoords@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A
bool MeshModelClass::read_stage_texcoords(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	MeshMatDescClass *matdesc = DefMatDesc;
	if (DefMatDesc->Has_UV(context->CurPass, context->CurTexStage)) {
		matdesc = &(context->AlternateMatDesc);
	}

	unsigned int elementcount = cload.Cur_Chunk_Length() / sizeof(W3dTexCoordStruct);
	context->TempUVArray.Uninitialised_Grow(elementcount);
	Vector2 *uvs = &context->TempUVArray[0];

	if (uvs != NULL) {
		unsigned int totalbytes = elementcount * sizeof(W3dTexCoordStruct);
		if (cload.Read(uvs, totalbytes) < totalbytes) {
			return false;
		}
		// The file stores V upside down relative to Direct3D.
		for (unsigned int i = 0; i < elementcount; i++) {
			uvs[i].Y = 1.0f - uvs[i].Y;
		}
	}
	matdesc->Install_UV_Array(context->CurPass, context->CurTexStage, uvs, elementcount);
	return true;
}

// FUNCTION: BFME2 0x00189B50 size=260 name=?read_Rva00189B50@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=?:placeholder tier=A
bool MeshModelClass::read_Rva00189B50(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	// A texture coordinate chunk read in one piece, with the V axis flipped in place, installed for the current pass on every stage.
	MeshMatDescClass *matdesc = DefMatDesc;
	unsigned int elementcount = cload.Cur_Chunk_Length() / sizeof(W3dTexCoordStruct);

	context->TempUVArray.Uninitialised_Grow(elementcount);
	Vector2 *uvarray = &context->TempUVArray[0];

	if (uvarray != NULL) {
		if (cload.Read(uvarray, elementcount * sizeof(Vector2)) < elementcount * sizeof(Vector2)) {
			return false;
		}
		for (unsigned int i = 0; i < elementcount; i++) {
			uvarray[i].Y = 1.0f - uvarray[i].Y;
		}
	}

	matdesc->Install_UV_Array(context->CurPass, -1, uvarray, elementcount);
	return true;
}


// FUNCTION: BFME2 0x00189C60 size=102 name=?post_process@MeshModelClass@@IAEXXZ evidence=N:ledger tier=A
void MeshModelClass::post_process()
{
	// skinned meshes should not have cull trees
	if (Get_Flag(MeshGeometryClass::SKIN)) {
		if (CullTree) {
			REF_PTR_RELEASE(CullTree);
		}
	}

	// turn off backface culling if the mesh is supposed to be two-sided
	if (Get_Flag(MeshGeometryClass::TWO_SIDED)) {
		DefMatDesc->Disable_Backface_Culling();
		if (AlternateMatDesc != NULL) {
			AlternateMatDesc->Disable_Backface_Culling();
		}
	}

	// if the mesh is sorting, pick an appropriate static sort level if default isn't set
	if (Get_Flag(SORT) && SortLevel == 0 && WW3D::Is_Munge_Sort_On_Load_Enabled()) {
		compute_static_sort_levels();
	}
}


