// FUNCTION: BFME2 0x0018A070 size=298 name=?install_materials@MeshModelClass@@IAEXPAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x0018A230 size=87 name=?Add_Shader@MeshLoadContextClass@@AAEHVShaderClass@@@Z evidence=N:ledger tier=A
int MeshLoadContextClass::Add_Shader(ShaderClass shader)
{
	int index = Shaders.Count();
	Shaders.Add(shader);
	return index;
}

// FUNCTION: BFME2 0x0018A290 size=93 name=?Add_Vertex_Material@MeshLoadContextClass@@AAEHPAVVertexMaterialClass@@@Z evidence=N:ledger tier=A
int MeshLoadContextClass::Add_Vertex_Material(VertexMaterialClass *vmat)
{
	vmat->Add_Ref();
	int index = VertexMaterials.Count();
	VertexMaterials.Add(vmat);
	return index;
}

// FUNCTION: BFME2 0x0018A2F0 size=93 name=?Add_Texture@MeshLoadContextClass@@AAEHPAVTextureClass@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x0018A350 size=29 name=?Add_Texture@MeshLoadContextClass@@QAEHABVBfmeHandleCX@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x0018A370 size=896 name=?Add_Legacy_Material@MeshLoadContextClass@@AAEXVShaderClass@@PAVVertexMaterialClass@@ABVBfmeHandleCX@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x0018A750 size=1336 name=?read_v3_materials@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x0018AC90 size=172 name=?read_shaders@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A
bool MeshModelClass::read_shaders(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	W3dShaderStruct shader;
	for (unsigned int i = 0; i < context->MatInfo.ShaderCount; i++) {
		if (cload.Read(&shader, sizeof(shader)) != sizeof(shader)) {
			return false;
		}
		ShaderClass newshader;
		W3dUtilityClass::Convert_Shader(shader, &newshader);

		context->Add_Shader(newshader);
	}
	return true;
}

// FUNCTION: BFME2 0x0018AD40 size=271 name=?read_vertex_materials@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A
bool MeshModelClass::read_vertex_materials(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	while (cload.Open_Chunk()) {
		VertexMaterialClass *vmat = ::new VertexMaterialClass();
		bool ok = vmat->Load_W3D(cload);
		if (ok != true) {
			vmat->Release_Ref();
			return ok;
		}
		context->Add_Vertex_Material(vmat);
		vmat->Release_Ref();
		cload.Close_Chunk();
	}
	return true;
}

// FUNCTION: BFME2 0x0018AE50 size=284 name=?read_textures@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x0018AF70 size=272 name=?read_fx_shaders@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x0018B080 size=160 name=?read_texture_stage@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A
bool MeshModelClass::read_texture_stage(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	while (cload.Open_Chunk()) {
		bool error = true;

		switch (cload.Cur_Chunk_ID()) {
		case W3D_CHUNK_TEXTURE_IDS:
			error = read_texture_ids(cload, context);
			break;

		case W3D_CHUNK_STAGE_TEXCOORDS:
		case W3D_CHUNK_TEXCOORDS:
			error = read_stage_texcoords(cload, context);
			break;

		case W3D_CHUNK_PER_FACE_TEXCOORD_IDS:
			error = read_per_face_texcoord_ids(cload, context);
			break;
		}

		if (error != true) {
			return error;
		}

		cload.Close_Chunk();
	}

	context->CurTexStage++;
	return true;
}


// FUNCTION: BFME2 0x0018B400 size=176 name=?read_material_pass@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A
bool MeshModelClass::read_material_pass(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	context->CurTexStage = 0;

	while (cload.Open_Chunk()) {
		bool error = true;

		switch (cload.Cur_Chunk_ID()) {
		case W3D_CHUNK_VERTEX_MATERIAL_IDS:
			error = read_vertex_material_ids(cload, context);
			break;

		case W3D_CHUNK_SHADER_IDS:
			error = read_shader_ids(cload, context);
			break;

		case W3D_CHUNK_FX_SHADER_IDS:
			error = read_Rva00188AF0(cload, context);
			break;

		case W3D_CHUNK_DCG:
			error = read_dcg(cload, context);
			break;

		case W3D_CHUNK_DIG:
			error = read_dig(cload, context);
			break;

		case W3D_CHUNK_SCG:
			// specular color arrays are not read
			error = true;
			break;

		case W3D_CHUNK_TEXTURE_STAGE:
			error = read_texture_stage(cload, context);
			break;

		case W3D_CHUNK_STAGE_TEXCOORDS:
			error = read_Rva00189B50(cload, context);
			break;

		default:
			break;
		}

		if (error != true) {
			return error;
		}
		cload.Close_Chunk();
	}

	context->CurPass++;
	return true;
}


// read_material_info has no retail copy of its own: its two callers (read_prelit_material here and read_chunks) expand it.
bool MeshModelClass::read_material_info(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	if (cload.Read(&(context->MatInfo), sizeof(W3dMaterialInfoStruct)) != sizeof(W3dMaterialInfoStruct)) {
		return false;
	}
	Set_Pass_Count(context->MatInfo.PassCount);
	return true;
}

// FUNCTION: BFME2 0x0018B4F0 size=204 name=?read_prelit_material@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=A
bool MeshModelClass::read_prelit_material(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	// If this chunk ID matches the selected prelit chunk ID then load it, otherwise skip it.
	if (cload.Cur_Chunk_ID() == context->PrelitChunkID) {

		// While there are chunks in the prelit material chunk wrapper...
		while (cload.Open_Chunk()) {
			bool error = true;

			switch (cload.Cur_Chunk_ID()) {
			case W3D_CHUNK_MATERIAL_INFO:
				error = read_material_info(cload, context);
				break;

			case W3D_CHUNK_VERTEX_MATERIALS:
				error = read_vertex_materials(cload, context);
				break;

			case W3D_CHUNK_SHADERS:
				error = read_shaders(cload, context);
				break;

			case W3D_CHUNK_TEXTURES:
				error = read_textures(cload, context);
				break;

			case W3D_CHUNK_MATERIAL_PASS:
				error = read_material_pass(cload, context);
				break;

			default:
				// Unknown chunk.
				break;
			}
			cload.Close_Chunk();
			if (error != true) {
				return error;
			}
		}
	}

	return true;
}


// FUNCTION: BFME2 0x0018B790 size=484 name=?read_chunks@MeshModelClass@@IAE_NAAVChunkLoadClass@@PAVMeshLoadContextClass@@@Z evidence=N:ledger tier=B hypothesis:K
bool MeshModelClass::read_chunks(ChunkLoadClass &cload, MeshLoadContextClass *context)
{
	while (cload.Open_Chunk()) {
		bool error = true;

		switch (cload.Cur_Chunk_ID()) {
		case W3D_CHUNK_VERTICES:
			error = read_vertices(cload, false);
			break;

		case W3D_CHUNK_VERTEX_NORMALS:
			error = read_vertex_normals(cload, false);
			break;

		case W3D_CHUNK_TEXCOORDS:
			error = read_texcoords(cload, context);
			break;

		case W3D_CHUNK_MATERIALS3:
			error = read_v3_materials(cload, context);
			break;

		case W3D_CHUNK_TRIANGLES:
			error = read_triangles(cload);
			break;

		case W3D_CHUNK_PER_TRI_MATERIALS:
			error = read_per_tri_materials(cload, context);
			break;

		case W3D_CHUNK_MESH_USER_TEXT:
			error = read_user_text(cload);
			break;

		case W3D_CHUNK_VERTEX_COLORS:
			error = read_vertex_colors(cload, context);
			break;

		case W3D_CHUNK_VERTEX_INFLUENCES:
			error = read_vertex_influences(cload);
			break;

		case W3D_CHUNK_VERTEX_SHADE_INDICES:
			error = read_vertex_shade_indices(cload);
			break;

		case W3D_CHUNK_PRELIT_UNLIT:
		case W3D_CHUNK_PRELIT_VERTEX:
		case W3D_CHUNK_PRELIT_LIGHTMAP_MULTI_PASS:
		case W3D_CHUNK_PRELIT_LIGHTMAP_MULTI_TEXTURE:
			read_prelit_material(cload, context);
			break;

		case W3D_CHUNK_MATERIAL_INFO:
			error = read_material_info(cload, context);
			break;

		case W3D_CHUNK_SHADERS:
			error = read_shaders(cload, context);
			break;

		case W3D_CHUNK_VERTEX_MATERIALS:
			error = read_vertex_materials(cload, context);
			break;

		case W3D_CHUNK_FX_SHADERS:
			error = read_fx_shaders(cload, context);
			break;

		case W3D_CHUNK_TEXTURES:
			error = read_textures(cload, context);
			break;

		case W3D_CHUNK_MATERIAL_PASS:
			error = read_material_pass(cload, context);
			break;

		case W3D_CHUNK_BFME_60:
			error = read_vertex_tangents(cload);
			break;

		case W3D_CHUNK_AABTREE:
			read_aabtree(cload);
			break;

		case W3D_CHUNK_BFME_61:
			error = read_vertex_binormals(cload);
			break;

		case W3D_CHUNK_VERTICES_SECOND_SET:
			error = read_vertices(cload, true);
			break;

		case W3D_CHUNK_VERTEX_NORMALS_SECOND_SET:
			error = read_vertex_normals(cload, true);
			break;

		default:
			break;
		}

		cload.Close_Chunk();

		if (error != true) {
			return error;
		}
	}

	return true;
}

// FUNCTION: BFME2 0x0018BA10 size=875 name=?Load_W3D@MeshModelClass@@UAE_NAAVChunkLoadClass@@@Z evidence=N:ledger tier=B hypothesis:K

